using System.Windows;
using Tune.Assets.Localization;
using Tune.Models.Music;
using Tune.Models.NewDialog;
using Tune.Services.FileDialog;
using Tune.Values.Static;

// Initially generated by AI, but edited.
namespace Tune.Components.UI
{
    /// <summary>
    /// Dialog content: pick a music either from the currently-playing track
    /// or from a local file.
    /// Result = the chosen music (null on cancel).
    /// </summary>
    public partial class AddMusic : DialogContentBase
    {
        // ==== Dependencies ====
        private readonly Music? _currentMusic;
        private readonly FileDialogService _fileDialogService = new();

        // ==== Dialog Contract ====
        /// <summary>
        /// Output. The music the user selected; null on cancel.
        /// The setter refreshes the button label so the UI never drifts
        /// out of sync with the state.
        /// </summary>
        private Music? _result;
        public Music? Result
        {
            get => _result;
            set
            {
                _result = value;
                UpdateSelectedMusicDisplay();
            }
        }

        // ==== Constructor ====
        /// <summary>
        /// <paramref name="currentMusic"/> is a context dependency, not a
        /// user-supplied argument, so it is injected via the constructor
        /// rather than through an Argument property.
        /// </summary>
        public AddMusic(Music? currentMusic)
        {
            InitializeComponent();
            DataContext = this;
            Height = 260;
            Width = 800;

            _currentMusic = currentMusic;

            ConfirmButton.Click += OnConfirmClick;
            CancelButton.Click += OnCancelClick;
        }

        // ==== Lifecycle ====
        /// <summary>
        /// Called by DialogService after the host window is loaded and
        /// CloseRequested has been subscribed. Safe to Confirm()/Cancel() here.
        /// </summary>
        protected override void OnShown()
        {
            // Initial paint; Result setter keeps it up to date afterwards.
            UpdateSelectedMusicDisplay();
        }

        // ==== UI Logic ====
        private void OnConfirmClick(object sender, RoutedEventArgs e)
        {
            if (Result == null)
            {
                MessageBox.Show(
                    Strings.NO_CONTENT,
                    Strings.APPLICATION_NAME,
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            Confirm();
        }

        private void OnCancelClick(object sender, RoutedEventArgs e)
        {
            Result = null;
            Cancel();
        }

        private void UpdateSelectedMusicDisplay()
        {
            SelectMusicButton.Text = Result != null
                ? Result.Metadata.Title
                : Strings.NO_CONTENT;
        }

        private void OnSelectNowPlayingClick(object sender, RoutedEventArgs e)
        {
            Result = _currentMusic;
        }

        private void OnSelectMusicButtonClick(object sender, RoutedEventArgs e)
        {
            var filePath = _fileDialogService.OpenMusicFile();
            if (string.IsNullOrEmpty(filePath))
                return;

            var music = new Music(filePath);
            if (music.notExists)
            {
                // TODO SHOW_TOAST
                MessageBox.Show(
                    LangStrings.MusicNotExistsOrUnknown,
                    Strings.APPLICATION_NAME,
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            Result = music;
        }
    }
}